                            .map(AttachmentSpec::getOwnerName)
                            .orElse(null)));
            indexSpecs.add(IndexSpecs.<Attachment, Long>single("spec.size", Long.class)
                    .indexFunc(attachment -> Optional.ofNullable(attachment.getSpec())
                            .map(AttachmentSpec::getSize)
